// Original TREE_GENERATOR geometry, exported in isolation from TouchDesigner.
// Roots, decorative connections and text are omitted.
export function paradigmTreeMarkup(c) {
  return `<div class="installation-tree"><canvas width="720" height="400" role="img" aria-label="${c.treeAlt}" tabindex="0" aria-describedby="paradigm-tree-help"></canvas></div><p id="paradigm-tree-help" class="tree-help">${c.rotate}</p>`;
}

// The mesh is generated by the original TouchDesigner L-system, in isolation.
export async function mountParadigmTree(scene,{signal,failure}) {
  const canvas=scene.querySelector('.installation-tree canvas');
  let yaw=.45,pitch=.35,drag=null,draw=()=>{};
  const clamp=n=>Math.max(-1.3,Math.min(1.3,n));
  const render=()=>draw(yaw,pitch);
  try {
    const response=await fetch('/assets/paradigm-crown.json',{signal});
    if(!response.ok)throw new Error('Tree mesh unavailable');
    const mesh=await response.json();
    if(signal.aborted)return;
    draw=mountCrownRenderer(canvas,mesh,signal,failure);
  } catch(error) {
    if(signal.aborted)return;
    scene.querySelector('.tree-help').textContent=failure;
    return;
  }
  const on=(event,callback)=>canvas.addEventListener(event,callback,{signal});
  on('pointerdown',event=>{
    if(event.button!==0||!event.isPrimary)return;
    drag={id:event.pointerId,x:event.clientX,y:event.clientY,yaw,pitch};
    canvas.setPointerCapture(event.pointerId);canvas.classList.add('is-dragging');
    canvas.focus({preventScroll:true});
  });
  on('pointermove',event=>{
    if(!drag||event.pointerId!==drag.id)return;
    yaw=drag.yaw+(event.clientX-drag.x)*.009;
    pitch=clamp(drag.pitch+(event.clientY-drag.y)*.006);render();
  });
  const finish=()=>{drag=null;canvas.classList.remove('is-dragging');};
  on('lostpointercapture',finish);on('pointercancel',finish);
  on('pointerup',event=>{if(canvas.hasPointerCapture(event.pointerId))canvas.releasePointerCapture(event.pointerId);finish();});
  on('keydown',event=>{
    if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(event.key))return;
    event.preventDefault();
    if(event.key==='Home'){yaw=.45;pitch=.35;}
    if(event.key==='ArrowLeft')yaw-=.12;
    if(event.key==='ArrowRight')yaw+=.12;
    if(event.key==='ArrowUp')pitch=clamp(pitch-.08);
    if(event.key==='ArrowDown')pitch=clamp(pitch+.08);
    render();
  });
  signal.addEventListener('abort',()=>{if(drag&&canvas.hasPointerCapture(drag.id))canvas.releasePointerCapture(drag.id);finish();},{once:true});
  render();
}

function mountCrownRenderer(canvas,mesh,signal,failure) {
  const gl=canvas.getContext('webgl',{alpha:false,antialias:true});
  if(!gl)throw new Error('WebGL unavailable');
  const vertex=`attribute vec3 position;attribute vec3 normal;
    uniform float yaw;uniform float pitch;uniform float aspect;varying vec3 n;
    vec3 turn(vec3 p){float c=cos(yaw),s=sin(yaw);p=vec3(c*p.x+s*p.z,p.y,-s*p.x+c*p.z);
      c=cos(pitch);s=sin(pitch);return vec3(p.x,c*p.y-s*p.z,s*p.y+c*p.z);}
    void main(){vec3 p=turn(position);n=turn(normal);float w=4.0-p.z;
      gl_Position=vec4(p.x*4.0/aspect,p.y*4.0,w-0.2,w);}`;
  const fragment=`precision mediump float;varying vec3 n;
    void main(){vec3 normal=normalize(n);if(!gl_FrontFacing)normal=-normal;
      float light=max(dot(normal,normalize(vec3(-0.6,0.9,1.5))),0.0);
      float ink=0.055+0.28*light;gl_FragColor=vec4(vec3(ink),1.0);}`;
  function shader(type,source){const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);
    if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw new Error('Tree shader failed');return s;}
  const shaders=[shader(gl.VERTEX_SHADER,vertex),shader(gl.FRAGMENT_SHADER,fragment)];
  const program=gl.createProgram();shaders.forEach(s=>gl.attachShader(program,s));gl.linkProgram(program);
  if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw new Error('Tree renderer failed');
  const min=[Infinity,Infinity,Infinity],max=[-Infinity,-Infinity,-Infinity];
  mesh.points.forEach(p=>p.forEach((v,i)=>{min[i]=Math.min(min[i],v);max[i]=Math.max(max[i],v);}));
  const center=min.map((v,i)=>(v+max[i])/2),scale=1.8/Math.max(...max.map((v,i)=>v-min[i]));
  const points=mesh.points.map(p=>p.map((v,i)=>(v-center[i])*scale));
  const data=[];
  for(let i=0;i<mesh.triangles.length;i+=3){
    const [a,b,c]=mesh.triangles.slice(i,i+3).map(j=>points[j]);
    const u=b.map((v,j)=>v-a[j]),v=c.map((w,j)=>w-a[j]);
    const n=[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]];
    const length=Math.hypot(...n);if(length<1e-12)continue;
    for(const p of [a,b,c])data.push(...p,...n.map(w=>w/length));
  }
  const buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);
  gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(data),gl.STATIC_DRAW);gl.useProgram(program);
  for(const [name,offset] of [['position',0],['normal',12]]){
    const index=gl.getAttribLocation(program,name);gl.enableVertexAttribArray(index);
    gl.vertexAttribPointer(index,3,gl.FLOAT,false,24,offset);
  }
  const uniforms=['yaw','pitch','aspect'].map(name=>gl.getUniformLocation(program,name));
  gl.enable(gl.DEPTH_TEST);gl.clearColor(1,1,1,1);
  let lastYaw=.45,lastPitch=.35;
  function paint(yaw=lastYaw,pitch=lastPitch){
    if(signal.aborted||gl.isContextLost())return;
    lastYaw=yaw;lastPitch=pitch;
    const r=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);
    canvas.width=Math.max(1,Math.round(r.width*dpr));canvas.height=Math.max(1,Math.round(r.height*dpr));
    gl.viewport(0,0,canvas.width,canvas.height);gl.useProgram(program);
    gl.uniform1f(uniforms[0],yaw);gl.uniform1f(uniforms[1],pitch);gl.uniform1f(uniforms[2],canvas.width/canvas.height);
    gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.drawArrays(gl.TRIANGLES,0,data.length/6);
  }
  const resize=new ResizeObserver(()=>paint());resize.observe(canvas);
  canvas.addEventListener('webglcontextlost',event=>{event.preventDefault();canvas.closest('.ad-scene').querySelector('.tree-help').textContent=failure;},{signal});
  signal.addEventListener('abort',()=>{resize.disconnect();gl.deleteBuffer(buffer);shaders.forEach(s=>gl.deleteShader(s));gl.deleteProgram(program);},{once:true});
  return paint;
}
